package com.trough.hot;
import android.app.Activity;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
/** Public music search and explicit track playback; no account/library impersonation. */
final class NativeMusicView extends LinearLayout {
 final Activity activity;final View root;final EditText composer;final ExecutorService worker=Executors.newSingleThreadExecutor();
 final TextView status,now,play;final LinearLayout results;final ScrollView scroll;final SeekBar seek;
 int generation;boolean closed,dragging;String query="";
 NativeMusicView(Activity a,View owner,EditText input){super(a);activity=a;root=owner;composer=input;setOrientation(VERTICAL);setPadding(dp(6),dp(8),dp(6),0);
  TextView search=label("⌕  Search songs and artists",17);search.setPadding(dp(14),0,dp(14),0);search.setBackground(background(0xff24313f));addView(search,new LayoutParams(-1,dp(44)));search.setOnClickListener(new OnClickListener(){public void onClick(View v){composer.setText("/search ");composer.setSelection(composer.length());composer.requestFocus();}});
  status=label("Search to find music",12);status.setTextColor(0xffa6b8c9);addView(status,new LayoutParams(-1,dp(28)));
  now=label("Choose a track",15);now.setMaxLines(2);addView(now,new LayoutParams(-1,dp(42)));
  LinearLayout controls=new LinearLayout(a);controls.setGravity(Gravity.CENTER_VERTICAL);play=label("▶",24);play.setGravity(Gravity.CENTER);play.setContentDescription("Play or pause music");controls.addView(play,new LayoutParams(dp(44),dp(40)));play.setOnClickListener(new OnClickListener(){public void onClick(View v){MediaPanel.controlMusic(activity,root,"toggle",0);paintPlayer();}});seek=new SeekBar(a);controls.addView(seek,new LayoutParams(0,dp(38),1));seek.setMax(1000);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){dragging=true;}public void onProgressChanged(SeekBar s,int p,boolean user){}public void onStopTrackingTouch(SeekBar s){Map<String,Object> state=MediaPanel.state(root);Object d=state.get("duration_ms");if(d instanceof Number)MediaPanel.controlMusic(activity,root,"seek",(int)(((Number)d).longValue()*s.getProgress()/1000));dragging=false;}});addView(controls);
  scroll=new ScrollView(a);scroll.setClipToPadding(false);results=new LinearLayout(a);results.setOrientation(VERTICAL);scroll.addView(results,new ScrollView.LayoutParams(-1,-2));addView(scroll,new LayoutParams(-1,0,1));
  String previous=a.getSharedPreferences("native-music",0).getString("query","");if(!previous.isEmpty())search(previous);
  post(new Runnable(){public void run(){if(closed)return;paintPlayer();postDelayed(this,700);}});
 }
 int dp(int n){return (int)(getResources().getDisplayMetrics().density*n+.5f);}
 android.graphics.drawable.GradientDrawable background(int color){android.graphics.drawable.GradientDrawable b=new android.graphics.drawable.GradientDrawable();b.setColor(color);b.setCornerRadius(dp(16));return b;}
 TextView label(String text,int size){TextView t=new TextView(activity);t.setText(text);t.setTextSize(size);t.setTextColor(0xfff1f4fa);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
 void bottomInset(int height){scroll.setPadding(0,0,0,Math.max(0,height));}
 void search(final String value){if(closed||value.trim().isEmpty())return;query=value.trim();final int version=++generation;status.setText("Searching · "+query);activity.getSharedPreferences("native-music",0).edit().putString("query",query).apply();worker.execute(new Runnable(){public void run(){try{final Map<String,Object> data=runTool(activity,"--flat-playlist","--dump-single-json","ytsearch8:"+value);post(new Runnable(){public void run(){if(closed||generation!=version)return;renderResults(data);}});}catch(final Exception error){post(new Runnable(){public void run(){if(!closed&&generation==version)status.setText("Search failed · "+error.getMessage());}});}}});}
 @SuppressWarnings("unchecked") void renderResults(Map<String,Object> data){results.removeAllViews();Object entries=data.get("entries");int count=0;if(entries instanceof List)for(Object entry:(List<?>)entries){if(!(entry instanceof Map))continue;final Map<String,Object> row=(Map<String,Object>)entry;final String id=Json.str(row,"id"),title=Json.str(row,"title");if(id==null||!id.matches("[A-Za-z0-9_-]{11}")||title==null)continue;String artist=Json.str(row,"channel");if(artist==null)artist="";LinearLayout item=new LinearLayout(activity);item.setOrientation(HORIZONTAL);item.setGravity(Gravity.CENTER_VERTICAL);item.setPadding(dp(10),dp(6),dp(10),dp(6));TextView icon=label("♪",25);icon.setTextColor(0xffffaabe);item.addView(icon,new LayoutParams(dp(34),dp(48)));LinearLayout info=new LinearLayout(activity);info.setOrientation(VERTICAL);TextView name=label(title,15);name.setMaxLines(2);info.addView(name);TextView by=label(artist,11);by.setTextColor(0xffa6b8c9);info.addView(by);item.addView(info,new LayoutParams(0,-2,1));TextView go=label("▶",18);item.addView(go,new LayoutParams(dp(28),dp(40)));results.addView(item,new LayoutParams(-1,-2));item.setContentDescription("Play "+title+" by "+artist);item.setOnClickListener(new OnClickListener(){public void onClick(View v){select(id,title);}});count++;}status.setText(count==0?"No results · try another search":"Songs · "+query);}
 void select(final String id,final String title){final int version=++generation;status.setText("Loading · "+title);worker.execute(new Runnable(){public void run(){try{final Map<String,Object> data=runTool(activity,"--dump-single-json","--skip-download","-f","bestaudio[ext=m4a]/bestaudio","https://www.youtube.com/watch?v="+id);final String url=Json.str(data,"url");if(url==null||!url.startsWith("https://"))throw new IOException("No playable stream");post(new Runnable(){public void run(){if(closed||generation!=version)return;MediaPanel.openMusic(activity,root,url,title);status.setText("Songs · "+query);paintPlayer();}});}catch(final Exception failure){post(new Runnable(){public void run(){if(!closed&&generation==version)status.setText("Could not load · "+failure.getMessage());}});}}});}
 static Map<String,Object> runTool(Activity activity,String... args)throws Exception{File tool=new File(activity.getFilesDir(),"work/trough-lab/dogshit-player/tools/yt-dlp"),out=File.createTempFile("music-",".json",activity.getCacheDir()),err=File.createTempFile("music-",".log",activity.getCacheDir());Process process=null;try{ArrayList<String> cmd=new ArrayList<String>();cmd.add(new File(Root.os(),"d/usr/bin/python3").getPath());cmd.add(tool.getAbsolutePath());cmd.add("--no-warnings");cmd.add("--no-playlist");cmd.add("--socket-timeout");cmd.add("10");Collections.addAll(cmd,args);ProcessBuilder builder=new ProcessBuilder(Root.command(activity,cmd.toArray(new String[cmd.size()])));builder.environment().putAll(Root.env(activity,activity.getCacheDir()));builder.redirectOutput(out);builder.redirectError(err);process=builder.start();if(!process.waitFor(40,TimeUnit.SECONDS))throw new IOException("Connection timed out");if(process.exitValue()!=0)throw new IOException("Source unavailable; try another track");if(out.length()>4*1024*1024)throw new IOException("Response too large");return Json.obj(Json.parse(new String(java.nio.file.Files.readAllBytes(out.toPath()),"UTF-8")));}finally{if(process!=null)process.destroy();out.delete();err.delete();}}
 void paintPlayer(){Map<String,Object> s=MediaPanel.state(root);boolean ready=Boolean.TRUE.equals(s.get("ready")),playing=Boolean.TRUE.equals(s.get("playing"));play.setText(playing?"Ⅱ":"▶");play.setEnabled(ready);String title=Json.str(s,"title");if(title!=null&&!title.isEmpty())now.setText(title);Object duration=s.get("duration_ms"),position=s.get("position_ms");if(!dragging&&duration instanceof Number&&position instanceof Number&&((Number)duration).longValue()>0)seek.setProgress((int)(1000*((Number)position).longValue()/((Number)duration).longValue()));String error=Json.str(s,"error");if(error!=null&&!error.isEmpty())status.setText(error);}
 @Override protected void onDetachedFromWindow(){closed=true;++generation;worker.shutdownNow();super.onDetachedFromWindow();}
}
